INSERT INTO `knowledge_base` (`id`, `title`, `category`, `summary`, `content`, `status`, `featured`, `display_order`, `tags`, `author_name`, `views`, `helpful_yes`, `helpful_no`, `created_at`, `updated_at`) VALUES
(1, 'How to Submit a Support Ticket', 'getting-started', 'Learn how to create and submit tickets for IT support.', '<h4>Step-by-Step Guide</h4><ol><li>Navigate to My Tickets</li><li>Click New Ticket</li><li>Fill in the details</li><li>Submit</li></ol>', 'published', 1, 0, NULL, 'IT Support Team', 1, 21, 15, '2026-06-08 17:24:38', '2026-07-23 11:21:41'),
(2, 'Understanding Ticket Statuses', 'tickets', 'Learn what each ticket status means.', '<h4>Ticket Lifecycle</h4><ul><li>New - Just submitted</li><li>Assigned - Given to technician</li><li>In Progress - Being worked on</li><li>Resolved - Fixed</li></ul>', 'published', 0, 0, NULL, 'IT Admin', 0, 0, 0, '2026-06-08 17:24:38', '2026-06-08 17:24:38'),
(3, 'Frequently Asked Questions', 'faq', 'Quick answers to common questions.', '<h4>Common Questions</h4><p><strong>Q: How do I check ticket status?</strong></p><p>A: Go to My Tickets.</p>', 'published', 0, 0, NULL, 'IT Support Team', 0, 0, 0, '2026-06-08 17:24:38', '2026-06-08 17:24:38'),
(4, 'How to Submit a Ticket', 'getting-started', 'Learn how to submit a support ticket through the EDPTech Helpdesk portal.', '<h3>Step-by-Step Guide</h3>\r\n<p>Submitting a ticket is the fastest way to get help from our IT support team.</p>\r\n\r\n<h4>1. Log in to the Portal</h4>\r\n<p>Visit the helpdesk portal and log in using your credentials. If you don\'t have an account, contact your department head.</p>\r\n\r\n<h4>2. Click "New Ticket"</h4>\r\n<p>Click the <strong>+ New Ticket</strong> button on the toolbar or sidebar.</p>\r\n\r\n<h4>3. Fill Out the Form</h4>\r\n<ul>\r\n  <li><strong>Title:</strong> Give a clear, descriptive title</li>\r\n  <li><strong>Description:</strong> Explain your issue in detail</li>\r\n  <li><strong>Location:</strong> Specify where the issue is occurring</li>\r\n  <li><strong>Priority:</strong> Select based on urgency</li>\r\n</ul>\r\n\r\n<h4>4. Submit</h4>\r\n<p>Click <strong>Submit Ticket</strong>. You\'ll receive a ticket number for tracking.</p>\r\n\r\n<div class="info-note">💡 <strong>Tip:</strong> Attach screenshots to help the support team understand your issue faster.</div>', 'published', 1, 1, 'ticket, getting started, help', 'System Admin', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(5, 'Understanding Ticket Priorities', 'tickets', 'Learn about the different priority levels and when to use each one.', '<h3>Priority Levels Explained</h3>\r\n<p>Choosing the right priority helps our team address issues in the correct order.</p>\r\n\r\n<h4>🔴 Critical</h4>\r\n<p><strong>Use when:</strong> System is down, security breach, or major outage affecting multiple users.</p>\r\n<p><strong>Response time:</strong> Within 30 minutes</p>\r\n\r\n<h4>🟠 High</h4>\r\n<p><strong>Use when:</strong> Significant issue affecting your work but workarounds exist.</p>\r\n<p><strong>Response time:</strong> Within 2 hours</p>\r\n\r\n<h4>🟡 Medium</h4>\r\n<p><strong>Use when:</strong> Non-critical issue or general assistance needed.</p>\r\n<p><strong>Response time:</strong> Within 8 hours</p>\r\n\r\n<h4>🟢 Low</h4>\r\n<p><strong>Use when:</strong> Minor issue, request, or inquiry.</p>\r\n<p><strong>Response time:</strong> Within 24 hours</p>\r\n\r\n<div class="warning">⚠️ <strong>Note:</strong> Misusing Critical priority may result in your ticket being downgraded.</div>', 'published', 1, 2, 'priority, tickets, sla', 'System Admin', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(6, 'How to Create a Job Order', 'job-orders', 'Step-by-step guide on creating and managing job orders.', '<h3>What is a Job Order?</h3>\r\n<p>A Job Order (JO) is a formal request for work or services from another department.</p>\r\n\r\n<h4>Creating a Job Order</h4>\r\n<ol>\r\n  <li>Navigate to <strong>Job Orders</strong> in the sidebar</li>\r\n  <li>Click <strong>New Job Order</strong></li>\r\n  <li>Select the target <strong>Department</strong> and <strong>Branch</strong></li>\r\n  <li>Describe the work needed in detail</li>\r\n  <li>Set a deadline if applicable</li>\r\n  <li>Click <strong>Submit</strong></li>\r\n</ol>\r\n\r\n<h4>Tracking Your Job Order</h4>\r\n<p>You can view the status of your job orders at any time:</p>\r\n<ul>\r\n  <li><strong>Pending:</strong> Awaiting review by recipient department</li>\r\n  <li><strong>Approved:</strong> Job order has been accepted</li>\r\n  <li><strong>Assigned:</strong> Assigned to a specific person</li>\r\n  <li><strong>Done:</strong> Work completed</li>\r\n</ul>\r\n\r\n<div class="info-note">💡 <strong>Tip:</strong> Be as specific as possible when describing the work needed to avoid delays.</div>', 'published', 1, 3, 'job order, request, department', 'System Admin', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(7, 'How to Submit a Requisition', 'requisitions', 'Guide on submitting requisition requests for supplies and materials.', '<h3>What is a Requisition?</h3>\r\n<p>A Requisition is a formal request for supplies, materials, or items needed for your work.</p>\r\n\r\n<h4>Submitting a Requisition</h4>\r\n<ol>\r\n  <li>Go to <strong>Requests</strong> in the sidebar</li>\r\n  <li>Click <strong>New Requisition</strong></li>\r\n  <li>Select the <strong>Request Type</strong> (Supplies, Equipment, etc.)</li>\r\n  <li>Add items with quantities and descriptions</li>\r\n  <li>Specify the <strong>Date Needed</strong></li>\r\n  <li>Click <strong>Submit Request</strong></li>\r\n</ol>\r\n\r\n<h4>Requisition Status</h4>\r\n<ul>\r\n  <li><strong>Pending:</strong> Under review</li>\r\n  <li><strong>Processing:</strong> Being prepared</li>\r\n  <li><strong>Released:</strong> Ready for pickup/delivery</li>\r\n  <li><strong>Received:</strong> Confirmed delivery</li>\r\n</ul>\r\n\r\n<div class="warning">⚠️ <strong>Important:</strong> Requisitions may require department head approval for items above certain values.</div>', 'published', 1, 4, 'requisition, request, supplies', 'System Admin', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(8, 'Password Reset Guide', 'account', 'How to reset your password and unlock your account.', '<h3>Forgot Your Password?</h3>\r\n<p>If you cannot log in, follow these steps:</p>\r\n\r\n<h4>Self-Service Reset</h4>\r\n<ol>\r\n  <li>Click <strong>Forgot Password</strong> on the login page</li>\r\n  <li>Enter your registered <strong>email address</strong></li>\r\n  <li>Check your email for the reset link</li>\r\n  <li>Click the link and create a new password</li>\r\n</ol>\r\n\r\n<h4>Password Requirements</h4>\r\n<ul>\r\n  <li>Minimum 8 characters</li>\r\n  <li>At least one uppercase letter</li>\r\n  <li>At least one number</li>\r\n  <li>At least one special character</li>\r\n</ul>\r\n\r\n<h4>Account Locked?</h4>\r\n<p>After 5 failed login attempts, your account will be locked for 15 minutes. Wait and try again, or contact IT support.</p>\r\n\r\n<div class="info-note">💡 <strong>Tip:</strong> Use a password manager to securely store your credentials.</div>', 'published', 0, 5, 'password, account, login, security', 'System Admin', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(9, 'Troubleshooting Common Printer Issues', 'troubleshooting', 'Solutions for common printer problems in the office.', '<h3>Printer Not Printing?</h3>\r\n<p>Try these solutions in order:</p>\r\n\r\n<h4>1. Check Physical Connections</h4>\r\n<ul>\r\n  <li>Ensure the printer is <strong>powered on</strong></li>\r\n  <li>Check that all <strong>cables are securely connected</strong></li>\r\n  <li>Verify the printer has <strong>paper and toner/ink</strong></li>\r\n</ul>\r\n\r\n<h4>2. Check Print Queue</h4>\r\n<p>Open the print queue on your computer and clear any stuck print jobs.</p>\r\n<ul>\r\n  <li>Windows: Settings → Devices → Printers → Open Queue</li>\r\n  <li>Mac: System Preferences → Printers → Open Print Queue</li>\r\n</ul>\r\n\r\n<h4>3. Restart Print Spooler</h4>\r\n<p>Sometimes the print spooler service needs to be restarted. Contact IT support if you need assistance with this.</p>\r\n\r\n<h4>4. Reinstall Printer Driver</h4>\r\n<p>If issues persist, the printer driver may need to be reinstalled. Submit a ticket for assistance.</p>\r\n\r\n<div class="warning">⚠️ <strong>Warning:</strong> Do not attempt to disassemble the printer. This should only be done by authorized technicians.</div>', 'published', 0, 6, 'printer, troubleshooting, hardware', 'IT Support', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(10, 'Getting Started with the Helpdesk Portal', 'getting-started', 'A beginner guide to navigating the EDPTech Helpdesk portal.', '<h3>Welcome to EDPTech Helpdesk!</h3>\r\n<p>This guide will help you get familiar with the portal.</p>\r\n\r\n<h4>Dashboard Overview</h4>\r\n<p>The dashboard shows:</p>\r\n<ul>\r\n  <li><strong>Recent Tickets:</strong> Your submitted tickets and their status</li>\r\n  <li><strong>Status Breakdown:</strong> Visual overview of your tickets</li>\r\n  <li><strong>Announcements:</strong> Important updates from IT</li>\r\n  <li><strong>Quick Actions:</strong> Fast access to common tasks</li>\r\n</ul>\r\n\r\n<h4>Navigation</h4>\r\n<ul>\r\n  <li><strong>Sidebar:</strong> Main navigation menu</li>\r\n  <li><strong>Toolbar:</strong> Quick access buttons</li>\r\n  <li><strong>Menu Bar:</strong> File, Edit, View, Tools, Help options</li>\r\n</ul>\r\n\r\n<h4>Key Features</h4>\r\n<ul>\r\n  <li>📝 <strong>Tickets:</strong> Submit and track support requests</li>\r\n  <li>📋 <strong>Job Orders:</strong> Request work from other departments</li>\r\n  <li>📩 <strong>Requisitions:</strong> Request supplies and materials</li>\r\n  <li>📚 <strong>Knowledge Base:</strong> Help articles and guides</li>\r\n</ul>\r\n\r\n<div class="info-note">💡 <strong>Tip:</strong> Bookmark the portal for quick access!</div>', 'published', 1, 7, 'getting started, portal, guide, beginner', 'System Admin', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(11, 'How to Check Ticket Status', 'tickets', 'Learn how to track the progress of your submitted tickets.', '<h3>Tracking Your Tickets</h3>\r\n<p>After submitting a ticket, you can check its status anytime.</p>\r\n\r\n<h4>Viewing Your Tickets</h4>\r\n<ol>\r\n  <li>Click <strong>My Tickets</strong> in the sidebar</li>\r\n  <li>You will see a list of all your submitted tickets</li>\r\n  <li>Click any ticket to view its details</li>\r\n</ol>\r\n\r\n<h4>Understanding Status</h4>\r\n<ul>\r\n  <li><strong>🆕 New:</strong> Ticket submitted, awaiting assignment</li>\r\n  <li><strong>📌 Assigned:</strong> Assigned to a support agent</li>\r\n  <li><strong>⚙️ In Progress:</strong> Agent is working on your issue</li>\r\n  <li><strong>⏳ Pending:</strong> Waiting for additional information or resources</li>\r\n  <li><strong>✅ Resolved:</strong> Issue has been fixed</li>\r\n  <li><strong>🔒 Closed:</strong> Ticket finalized</li>\r\n</ul>\r\n\r\n<h4>Adding Comments</h4>\r\n<p>You can add comments to your ticket to provide additional information or ask for updates.</p>\r\n\r\n<div class="info-note">💡 <strong>Tip:</strong> You\'ll receive notifications when your ticket status changes.</div>', 'published', 0, 8, 'tickets, status, tracking', 'System Admin', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(12, 'Computer Maintenance Tips', 'troubleshooting', 'Regular maintenance tips to keep your computer running smoothly.', '<h3>Keep Your Computer Healthy</h3>\r\n<p>Follow these tips to maintain optimal performance.</p>\r\n\r\n<h4>Weekly Tasks</h4>\r\n<ul>\r\n  <li><strong>Restart your computer</strong> at least once a week</li>\r\n  <li><strong>Clear browser cache</strong> and temporary files</li>\r\n  <li><strong>Update software</strong> when prompted</li>\r\n</ul>\r\n\r\n<h4>Monthly Tasks</h4>\r\n<ul>\r\n  <li><strong>Run disk cleanup</strong> to free up space</li>\r\n  <li><strong>Check for Windows updates</strong></li>\r\n  <li><strong>Backup important files</strong> to network drive</li>\r\n  <li><strong>Scan for viruses</strong> using company antivirus</li>\r\n</ul>\r\n\r\n<h4>Performance Tips</h4>\r\n<ul>\r\n  <li>Close unused programs and browser tabs</li>\r\n  <li>Avoid installing unauthorized software</li>\r\n  <li>Keep your desktop organized</li>\r\n  <li>Save files to network drives, not local storage</li>\r\n</ul>\r\n\r\n<div class="warning">⚠️ <strong>Warning:</strong> Do not disable or uninstall company-installed security software.</div>', 'published', 0, 9, 'computer, maintenance, performance, tips', 'IT Support', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01'),
(13, 'Frequently Asked Questions (FAQ)', 'faq', 'Answers to the most commonly asked questions about the helpdesk system.', '<h3>Common Questions</h3>\r\n\r\n<h4>Q: How long does it take to get a response?</h4>\r\n<p>A: Response times vary by priority. Critical issues are addressed within 30 minutes, while low-priority requests may take up to 24 hours.</p>\r\n\r\n<h4>Q: Can I edit my ticket after submitting?</h4>\r\n<p>A: You can add comments to your ticket at any time. If you need to change the title or description, contact the assigned agent.</p>\r\n\r\n<h4>Q: What if my issue is urgent after hours?</h4>\r\n<p>A: For emergencies outside business hours, contact the IT emergency line at ext. 9911.</p>\r\n\r\n<h4>Q: How do I know who is working on my ticket?</h4>\r\n<p>A: Open your ticket and check the "Assigned To" field. You\'ll see the name of the support agent handling your issue.</p>\r\n\r\n<h4>Q: Can I reopen a closed ticket?</h4>\r\n<p>A: Closed tickets cannot be reopened. Please submit a new ticket referencing your previous ticket number.</p>\r\n\r\n<h4>Q: What browsers are supported?</h4>\r\n<p>A: The portal works best with Chrome, Firefox, Edge, and Safari (latest versions).</p>\r\n\r\n<div class="info-note">💡 <strong>Tip:</strong> Search the Knowledge Base before submitting a ticket — your question may already be answered!</div>', 'published', 0, 10, 'faq, questions, help, common issues', 'System Admin', 0, 0, 0, '2026-07-23 11:36:01', '2026-07-23 11:36:01');
